ttest_power <- function(n, d, alpha) {
  df <- 2 * n - 2
  ncp <- d * sqrt(n / 2)
  tc <- qt(1 - alpha / 2, df)
  suppressWarnings(pt(tc, df, ncp = ncp, lower.tail = FALSE) + pt(-tc, df, ncp = ncp))
}

