prior_prec <- 1 / prior[["sd"]]^2
post_prec <- prior_prec + data_prec
post_mean <- (prior_prec * prior[["mean"]] + data_prec * published_effect) / post_prec
post_sd <- sqrt(1 / post_prec)
shrinkage <- post_mean / published_effect

